local controller_base = get_or_create_global_variable('Quest/Base/QuestControllerBase')

---@class ShortStoryFrierenBreadRecipeController : QuestControllerBase
local local_class = newclass('ShortStoryFrierenBreadRecipeController', controller_base)

function local_class:init(cs_controller)
	self.super:init(cs_controller)

	-- 사용할 섹션 스크립트 정보. 주석 해제하고 사용
	self.script_config = {
		HasPreSection = false,
		NormalSectionCount = 1,
		HasPostSection = false
	}

	self.omelet_item = {
		omelet_data = {},
		dish_data = {},

		---@type fun(this:self)
		load = function(this)
			local target_pos = field_util.get_marker_pos('sub_bread_center_pos')
			local offset_data = {
				vector(2.5, 0.8, 0),
				vector(2.5, 0.8, 1),
				vector(2.5, 0.8, -1),
			}

			for i = 1, #offset_data do
				local dish_item = quest_drop_item_util.create_item({
					pos = target_pos + offset_data[i],
					item_id = 21466,
					spr_scale = 1,
					loot_state = quest_drop_item_loot_state.dont_find_looter,
				})

				local omelet_item = quest_drop_item_util.create_item({
					pos = target_pos + offset_data[i] + vector(0, 0.05, 0),
					item_id = 21465,
					spr_scale = 1,
					loot_state = quest_drop_item_loot_state.dont_find_looter,
				})

				table.insert(this.dish_data, dish_item)
				table.insert(this.omelet_data, omelet_item)
			end
		end,

		---@type fun(this:self,num:number):DropItem
		get_omelet = function(this, num)
			return this.omelet_data[num]
		end,

		---@type fun(this:self)
		dispose = function(this)
			for i = 1, #this.dish_data do
				quest_drop_item_util.dispose_item(this.dish_data[i])
			end

			for i = 1, #this.omelet_data do
				quest_drop_item_util.dispose_item(this.omelet_data[i])
			end

			this.dish_data = {}
			this.omelet_data = {}
		end,
	}
end

function local_class:load_resource()
end

function local_class:dispose()
	self.super:dispose()
	self.omelet_item:dispose()
end

function local_class:on_event(e)
	return false
end

function local_class:on_stage_loaded()
end

function local_class:on_stage_end()
end

return local_class

