		select_load_async = function(this, state_idx, area_idx, npc_list, use_pre_fix_of_name)
			local function create_specs(state_idx, area_idx, npc_list, pre_fix)
				use_pre_fix_of_name = lua_helper.get_or_default(use_pre_fix_of_name, false)

				local key = 'inst_%d_%d_%d'

				local ret = {}

				for i = 1, #npc_list do
					if use_pre_fix_of_name then
						key = npc_list[i] .. '_inst_%d_%d_%d'
					end

					ret[string.format(key, state_idx, area_idx, i)] = npc_list[i]
				end

				return ret
			end

			if npc_list ~= nil and #npc_list > 0 then
				if this.select_npcs == nil then
					this.select_npcs = load_util.create_dynamic_npcs_async(create_specs(state_idx, area_idx, npc_list))
				else
					local add_dyn_npcs = load_util.create_dynamic_npcs_async(create_specs(state_idx, area_idx, npc_list))

					for name, npc in pairs(add_dyn_npcs) do
						table.insert(this.select_npcs, npc)
					end
				end
			end
		end,

		foreach_npc = function(this, action)
			local idx = 1
			for name, npc in pairs(this.select_npcs) do
				action(idx, npc)

				idx = idx + 1
			end
		end,

		empty_npc_list = function(this)
			if this.select_npcs == nil then
				return true
			end

			return false
		end,

		dispose = function(this)
			if this.select_npcs ~= nil then
				load_util.dispose_dynamic_npcs(this.select_npcs)

				this.select_npcs = nil
			end
