function local_class:enter()
	self:set_quest_drop_item()

	self:set_pre_npc_data()

	self:set_current_scene_npc()

	quest_marker_util.add_auto_control(self.firework_quest_marker_name, {
		{ zone = 'night_field', target = self.markers.fireworks_center() },
		{ zone = 'tavern_field', target = self.field_object.pub_exit() },
		{ zone = 'room_a_field', target = get_field_object('room_a_outer_1') },
		{ zone = 'room_b_field', target = get_field_object('room_b_outer_1') },
		{ zone = 'room_c_field', target = get_field_object('room_c_outer_1') },
	}, 'main_quest_1', nil, true)
	quest_marker_util.add_auto_control(self.concert_quest_marker_name, {
		{ zone = 'night_field', target = self.markers.concert_hall_center() },
		{ zone = 'tavern_field', target = self.field_object.pub_exit() },
		{ zone = 'room_a_field', target = get_field_object('room_a_outer_1') },
		{ zone = 'room_b_field', target = get_field_object('room_b_outer_1') },
		{ zone = 'room_c_field', target = get_field_object('room_c_outer_1') },
	}, 'main_quest_2', nil, true)

	character_util.add_listener(self.characters.knight(), self.controller)

	scene_util.hide_weapon(self.characters.pirate())

	--self:force_pub_event_state_change()

	-- 레드 미리 애니 셋팅
	start_coroutine(function()
		local ranger_red = self.characters.teatan_ranger_red()

		field_object_util.set_active_state(ranger_red, active_state_type.enabled)

		coroutine.yield(nil)

		wait_for_sec(0.1)

		scene_util.set_anim(ranger_red, self,
				{ name = 'jingak' })

		ranger_red.SpineController:ForceUpdateSpines(0.1)

		wait_for_sec(0.9)
		character_util.set_anim_time_scale(ranger_red, 0)

		coroutine.yield(nil)

		field_object_util.set_active_state(ranger_red, active_state_type.disabled)
	end)
end

function local_class:start()
	message_system:Subscribe(self, typeof(CS.Oak.InteractEvent), 'on_event')
	message_system:Subscribe(self, typeof(CS.Oak.ZoneEnterEvent), 'on_zone_enter_event')
	message_system:Subscribe(self, typeof(CS.Oak.ZoneLeaveEvent), 'on_zone_leave_event')
	message_system:Subscribe(self, typeof(CS.Oak.StageEndEvent), 'on_stage_end_event')

	-- EventGroupManager 에 있는 사회자 가져오기
	local merchant = self.pooled_characters('s6_restaurant_area', 'merchant')

	merchant.Hitbox = CS.Oak.Hitbox(vector(1, 0.75, 2.5))

	self:load_night_sky_bg()
end

function local_class:exit()
	message_system:Unsubscribe(self, typeof(CS.Oak.InteractEvent))
	message_system:Unsubscribe(self, typeof(CS.Oak.ZoneEnterEvent))
	message_system:Unsubscribe(self, typeof(CS.Oak.ZoneLeaveEvent))
	message_system:Unsubscribe(self, typeof(CS.Oak.TouchEvent))
	message_system:Unsubscribe(self, typeof(CS.Oak.StageEndEvent))

	character_util.remove_relate_event(self.characters.knight(), self.controller)

	if self.fx ~= nil then
		self.fx:dispose(true)
	end

	if self.items ~= nil then
		self.items:dispose_all()
	end

	if self.dyn_npcs ~= nil then
		self.dyn_npcs:dispose()
	end

	if self.loop_sfx ~= nil then
		self.loop_sfx:Stop()
		self.loop_sfx = nil
	end

	field_object_util.set_active_state(self.field_object.night_sky_bg(), active_state_type.disabled)

	quest_marker_util.remove_auto_control(self.firework_quest_marker_name)
	quest_marker_util.remove_auto_control(self.concert_quest_marker_name)
end

function local_class:dispose()
	self.controller = nil
	self.cs_controller = nil
	self.cs_section = nil
end

function local_class:on_event(e)
	if lua_helper.type_compare(e, CS.Oak.InteractEvent) then
		return self:on_interact_event(e)
	end

	return false
end

function local_class:on_interact_event(e)
	if lua_helper.reference_equals(e.Target, self.field_object.pub_chair()) then
		self:start_scene(self.play_pub_event, self)

		return true
	elseif lua_helper.reference_equals(e.Target, self.characters.knight()) then
		if not self.knight_show_emoticon then
			start_coroutine(function()
				self.knight_show_emoticon = true

				scene_util.play_emoticon_action(e.Target, self, nil, nil, nil, 'sleep')

				self.knight_show_emoticon = false
			end)
		end

		return true
	end

	return false
end

function local_class:on_zone_enter_event(e)
	local leader = get_party_leader()

	if self.current_state == self.states.enjoy_festival then
		local event_zone = self.event_zone_info[self.states.enjoy_festival]

		if type_util.is_zone_full_enter(e, leader, event_zone[self.event_region.fireworks.index].zone_name) and
				not self.event_region.fireworks.clear then
			self:start_scene(self.enjoy_fireworks_event, self):Then(function()
				local librarian_event_group = self.controller.event_controller
						:get_group('librarian_day_2_night')

				-- 란 이벤트 활성화
				librarian_event_group:enable_trigger()
			end)

			return true
		elseif type_util.is_zone_full_enter(e, leader, event_zone[self.event_region.concert_hall.index].zone_name) and
				not self.event_region.concert_hall.clear then
			self:start_scene(self.enjoy_concert_event, self)

			return true
		elseif type_util.is_zone_full_enter(e, leader, event_zone[self.event_region.concert_hall_loop.index].zone_name) then
			if self.event_region.concert_hall.clear then
				music_player_util.play_stage_music({ name = 'bgm_iron_teatan', state = 'event', mix = 4})
			else
				start_coroutine(self.concert_hall_before_event, self)
			end

			return true
		elseif type_util.is_zone_full_enter(e, leader, event_zone[self.event_region.tavern.index].zone_name) then
			start_coroutine(function()
				self.loop_sfx = music_player_util.play_sfx({ sfx_name = '01_amb_restaurant_01', volume = 0.3, loop = true })
			end)

			return true
		end
	elseif self.current_state == self.states.pub_brawl then
		local event_zone = self.event_zone_info[self.states.pub_brawl]

		if type_util.is_zone_full_enter(e, leader, event_zone[self.event_region.tavern.index].zone_name) then
			start_coroutine(function()
				self.loop_sfx = music_player_util.play_sfx({ sfx_name = '01_amb_restaurant_01', volume = 0.3, loop = true })
			end)

			return true
		elseif type_util.is_zone_full_enter(e, leader, event_zone[self.event_region.concert_hall_loop.index].zone_name) then
			if self.event_region.concert_hall.clear then
				music_player_util.play_stage_music({ name = 'bgm_iron_teatan', state = 'event', mix = 4})
			else
				start_coroutine(self.concert_hall_before_event, self)
			end

			return true
		end
	end


	return false
end

function local_class:on_zone_leave_event(e)
	local leader = get_party_leader()

	if self.current_state == self.states.enjoy_festival then
		local event_zone = self.event_zone_info[self.states.enjoy_festival]

		if type_util.is_zone_full_leave(e, leader, event_zone[self.event_region.concert_hall_loop.index].zone_name) then
			if not self.event_region.concert_hall.clear then
				self.loop_escape = true
				self.concert_before_event_loop = false

				if self.concert_before_event_talker ~= nil then
					speech_bubble_util.remove_bubble(self.concert_before_event_talker)
				end
			else
				start_coroutine(function()
					music_player_util.set_stage_music_clip_async(
							{ name = 'ondemand/short_story_milkyway/audio:bgm_milkyway_night', state = 'field' })
					music_player_util.play_stage_music({ state = 'field', volume = 1 })
				end)
			end

			return true
		end
	elseif self.current_state == self.states.pub_brawl then
		local event_zone = self.event_zone_info[self.states.pub_brawl]

		if type_util.is_zone_full_leave(e, leader, event_zone[self.event_region.tavern.index].zone_name) then
			if self.loop_sfx ~= nil then
				self.loop_sfx:Stop()
				self.loop_sfx = nil
			end

			return true
		elseif type_util.is_zone_full_leave(e, leader, event_zone[self.event_region.concert_hall_loop.index].zone_name) then
			if self.event_region.concert_hall.clear then
				start_coroutine(function()
					music_player_util.set_stage_music_clip_async(
							{ name = 'ondemand/short_story_milkyway/audio:bgm_milkyway_night', state = 'field' })
					music_player_util.play_stage_music({ state = 'field', volume = 1 })
				end)
			end

			return true
		end
	end

	return false
end

function local_class:on_touch_event(e)
	if self.qte_activity_info.cur_qte_type == self.qte_type.swipe then
		if e.TouchEventType == CS.Oak.TouchEventType.SwipeUp then
			self.qte_activity_info.swipe_type = direction_constants.up

			return true
		elseif e.TouchEventType == CS.Oak.TouchEventType.SwipeRight then
			self.qte_activity_info.swipe_type = direction_constants.right

			return true
		elseif e.TouchEventType == CS.Oak.TouchEventType.SwipeDown then
			self.qte_activity_info.swipe_type = direction_constants.down

			return true
		elseif e.TouchEventType == CS.Oak.TouchEventType.SwipeLeft then
			self.qte_activity_info.swipe_type = direction_constants.left

			return true
		end
	end

	if self.qte_activity_info.cur_qte_type == self.qte_type.tap then
		if e.TouchEventType == CS.Oak.TouchEventType.TouchDown then
			self.qte_activity_info.tap_count = self.qte_activity_info.tap_count + 1

			if self.qte_activity_info.tap_count_callback ~= nil then
				self.qte_activity_info:tap_count_callback(self.qte_activity_info.tap_count)
			end

			return true
		end
	end

	return false
end

function local_class:on_stage_end_event(e)
	message_system:Unsubscribe(self, typeof(CS.Oak.TouchEvent))

	return true
end

--region start scene
function local_class:start_scene(func, ...)
	local args = { ... }
	local routine = function()
		-- 이전 리더에 대한 정보를 미리 캐싱해둬야 해제가 가능함
		local cached_leader = get_party_leader()

		sp_util.enter_scene(nil)

		yield_return_func(func, table.unpack(args))

		sp_util.exit_scene({ show_weapon = false }, cached_leader)
	end

	return start_coroutine(routine)
end
--endregion

