function local_class:remove_pre_npcs()
	local group = self.controller.event_controller:get_group('s6_cafe_area')

	-- 카페 내 손님 NPC 제거
	for i = 1, self.cafe_guest_count do
		local handler = group:get_handler('guest_' .. i)

		if handler ~= nil then
			handler:dispose()
		end
	end

	local exception_object = {
		self.characters.teatan_hero(),
		self.characters.knight(),
		self.characters.princess(),
		self.characters.captain(),
		self.characters.civilian_kid_boy(),
		self.characters.innuit_kid_boy(),
		self.characters.teatan_kid_girl(),
	}

	for i = 1, #self.pre_npc_data do
		local pre_npc_data = self.pre_npc_data[i]

		linq(pre_npc_data):foreach(function(_, npc_data)
			local npc = get_character(npc_data.name)

			if npc == nil then
				return
			end

			for j = 1, #exception_object do
				if lua_helper.reference_equals(exception_object[j], npc) then
					character_util.remove_anim_and_emotion(npc)
					character_util.set_position(npc, vector(999, 0, 999))

					return
				end
			end

			field_object_util.set_active_state(npc, active_state_type.disabled)
		end)
	end
end
