function local_class:enjoy_fireworks_event()
	local pirate = self.characters.pirate()
	local star_girl = self.characters.star_girl()
	local group = self.controller.event_controller:get_group('s6_firework_area')
	local mc = self.pooled_characters(group, 'mc')

	local move_end_key = 'party_align'

	music_player_util.change_stage_music_volume('field', 0.6)

	camera_util.move(self.markers.camera(1, 1), 1)

	wp_util.move_with_end_callback(pirate, self.markers.pirate(1, 1), nil, 1, self, move_end_key, { last_direction = 'up' })
	wp_util.move_with_end_callback(star_girl, self.markers.star_girl(1, 1), nil, 1, self, move_end_key, { last_direction = 'up' })

	wp_util.wait_move_end(self, move_end_key)

	-- 카메라 포커스와 레나 정렬이 완료되면 0.5초 대기
	wait_for_sec(0.5)

	scene_util.set_direction(pirate, 'left', false)

	-- 레나 (right, idle, idle): 여기서 불꽃놀이를 하는 거야?
	scene_util.play_normal_speech_action(star_girl, self,
			{ dir = 'right', sfx = '01_swing_01' },
			nil,
			{ name = 'smile', keep = true },
			{ key = 'ss_milkyway_main_s6_1_1', skip = true })

	-- 레이첼 (left, smile, idle): 응! 좀있다가 하늘에서 불꽃이 터질거야.
	scene_util.play_normal_speech_action(pirate, self,
			{ dir = 'left', sfx = false },
			nil,
			{ name = 'smile' },
			{ key = 'ss_milkyway_main_s6_1_2', skip = true })

	-- 레나 (right, idle, cross_arm): 음… 대체 어떤 느낌이지?
	scene_util.play_normal_speech_action(star_girl, self,
			{ dir = 'right', sfx = false },
			{ name = 'cross_arm' },
			{ name = 'sleep_deep' },
			{ key = 'ss_milkyway_main_s6_1_3', skip = true })

	-- 레나 (right, idle, bomb_idle): 책에서 봤을 때는 그냥 하늘에서 불꽃이 터진다고만 적혀있었는데….
	scene_util.play_normal_speech_action(star_girl, self,
			{ dir = 'right', sfx = false },
			{ name = 'bomb_idle' },
			{ name = 'idle' },
			{ key = 'ss_milkyway_main_s6_1_4', skip = true })

	-- 대사 출력시 레나, 레이첼 (up, idle)
	scene_util.set_direction(pirate, 'up', false)
	scene_util.set_direction(star_girl, 'up', false)

	-- 상인 (down, smile, idle) : 자, 여러분! 오래 기다리셨습니다!
	music_player_util.play_sfx_one_shot('01_swing_01')
	scene_util.play_normal_speech_action(mc, self,
			{ dir = 'down', sfx = false },
			nil,
			{ name = 'smile', keep = true },
			{ key = 'ss_milkyway_main_s6_1_5', skip = true })

	-- 상인 (down, smile, release 2회) : 이제, 모두가 기다리고 기다리던…
	scene_util.play_normal_speech_action(mc, self,
			{ dir = 'down', sfx = false },
			{ name = 'release', count = 2 },
			{ name = 'smile', keep = true },
			{ key = 'ss_milkyway_main_s6_1_6', skip = true })

	-- 상인 (down, smile, cast2): [shout] 불꽃놀이가 시작됩니다!!!
	-- shout 말풍선의 대사는 한번에 나오게 출력
	-- 위와 동시에 카메라 shake 0.1 세기로 0.3초 출력
	-- 01_gatcha_spotlight_01 + 03_dialogue_positive_01
	music_player_util.play_sfx_one_shot('01_gatcha_spotlight_01')
	music_player_util.play_sfx_one_shot('03_dialogue_positive_01')
	camera_util.shake(0.1, 0.3)
	scene_util.play_shout_speech_action(mc, self,
			{ dir = 'down', sfx = false },
			{ name = 'cast2' },
			nil,
			{ key = 'ss_milkyway_main_s6_1_7', type_speed = 0, skip = true })

	do
		local dyn_npc = nil

		-- 여자꼬마 (up, idle, jump) : 우와아아!! 불꽃놀이!!
		start_coroutine(function()
			dyn_npc = self.pooled_characters(group, 'firework_event_npc_7')

			music_player_util.play_sfx_one_shot('01_crowd_clap_02')
			character_util.normal_jump(dyn_npc, true)
			scene_util.play_normal_speech_action(dyn_npc, self,
					{ dir = 'up', sfx = false },
					nil,
					nil,
					{ key = 'ss_milkyway_main_s6_1_8', skip = false })
		end)

		-- 위 대사 출력 시작 0.3초 뒤 대사 출력
		wait_for_sec(0.3)

		-- 남자꼬마 (up, idle, cast2): 불꽃놀이!!! 얏호!!!
		start_coroutine(function()
			dyn_npc = self.pooled_characters(group, 'firework_event_npc_2')

			scene_util.play_normal_speech_action(dyn_npc, self,
					{ dir = 'up', sfx = false },
					nil,
					nil,
					{ key = 'ss_milkyway_main_s6_1_9', skip = false })
		end)

		-- 위 대사 출력 시작 0.2초 뒤 대사 출력
		wait_for_sec(0.2)

		-- 할아버지 (right, idle, idle): 거 옛날 생각나는구먼.
		start_coroutine(function()
			dyn_npc = self.pooled_characters(group, 'firework_event_npc_6')

			scene_util.play_normal_speech_action(dyn_npc, self,
					{ dir = 'up', sfx = false },
					nil,
					nil,
					{ key = 'ss_milkyway_main_s6_1_10', skip = false })
		end)

		-- 위 대사 출력 시작 0.1초 뒤 아래 대사 출력
		wait_for_sec(0.1)

		start_coroutine(function()
			dyn_npc = self.pooled_characters(group, 'firework_event_npc_9')

			-- 남1 (up, idle): 오래간만에 제대로 보겠는걸…
			scene_util.play_normal_speech_action(dyn_npc, self,
					{ dir = 'up', sfx = false },
					nil,
					nil,
					{ key = 'ss_milkyway_main_s6_1_11', skip = false })
		end)

		-- 위 대사들 출력 0.1초 뒤 대사 출력
		wait_for_sec(0.1)

		start_coroutine(function()
			dyn_npc = self.pooled_characters(group, 'firework_event_npc_10')

			-- 여1 (up, idle): 오예! 페이스 브레이크에 올려야이지!
			scene_util.play_normal_speech_action(dyn_npc, self,
					{ dir = 'up', sfx = false },
					nil,
					nil,
					{ key = 'ss_milkyway_main_s6_1_12', skip = false })
		end)

		local speech_end = false
		start_coroutine(function()
			dyn_npc = self.pooled_characters(group, 'firework_event_npc_4')

			-- 불량남 (up, idle): 이것만 기다렸다고!
			scene_util.play_normal_speech_action(dyn_npc, self,
					{ dir = 'up', sfx = false },
					nil,
					nil,
					{ key = 'ss_milkyway_main_s6_1_13', skip = false })
			speech_end = true
		end)

		-- 위 스킵 불가 대사 출력이 모두 끝나고 0.2초 후 아래 대사 진행
		while not speech_end do
			coroutine.yield(nil)
		end

		wait_for_sec(0.5)

		-- 상인 (down, smile, cast2) : 모두 하늘을 쳐다봐주세요!
		music_player_util.play_sfx_one_shot('03_dialogue_emphasize_01')
		scene_util.play_normal_speech_action(mc, self,
				{ dir = 'down', sfx = false },
				{ name = 'cast2', keep = true },
				{ name = 'smile', keep = true },
				{ key = 'ss_milkyway_main_s6_1_14', skip = false })
	end

	-- 3초에 걸쳐 화면 (x축 -55.5, z -55 )위치로 이동
	camera_util.move(self.markers.camera(1, 2), 3)

	-- 화면 이동 시작하고 1.5초 뒤 카메라 1.5초에 걸쳐 5크기로 줌 아웃
	wait_for_sec(1.5)

	camera_util.resize_by_ratio_async(5, 1.5)

	-- 1초 대기.
	wait_for_sec(1)

	self.fireworks_event_paused = true

	local beach_sfx = music_player_util.play_sfx({ sfx_name = '01_amb_beach_02', loop = true, fade_in_time = 0 })
	music_player_util.play_sfx_one_shot('01_crowd_clap_03', 0.6)

	start_coroutine(self.shot_firecracker_event, self)

	while self.fireworks_event_paused do
		coroutine.yield(nil)
	end

	-- 3단계 폭죽이 한번 진행된 이후, 3초 대기
	wait_for_sec(3)

	beach_sfx:FadeOut(2)

	-- 이후 1.5초에 걸쳐 화면 fade out
	screen_util.fade_out_async(1.5, unity_class.color.black, 'linear')

	-- 1초 대기
	wait_for_sec(0.5)

	self.fireworks_loop = false

	character_util.set_position(pirate, self.markers.pirate(1, 2))
	scene_util.set_direction(pirate, 'left', false)
	scene_util.set_emotion(pirate, self, 'smile')
	character_util.set_position(star_girl, self.markers.star_girl(1, 2))
	scene_util.set_direction(star_girl, 'right', false)
	scene_util.set_emotion(star_girl, self, 'smile')

	-- 카메라 4 크기
	camera_util.resize_to_default_async(0.1)
	camera_util.move_async(pirate.Position + vector(-0.5, 0, 0), 0)

	-- 관객 중 할아버지 npc 0.5칸 위로 위치 이동
	local dyn_npc = self.pooled_characters(group, 'firework_event_npc_6')

	character_util.set_position(dyn_npc, dyn_npc.Position + vector(0, 0, 0.5))
	scene_util.set_direction(dyn_npc, 'right', false)

	self:set_dyn_npc_oneline_state(self.event_region.fireworks)

	wait_for_sec(0.5)

	-- 1초에 걸쳐 아래의 레나, 레이첼 중심을 포커스로 fade in
	screen_util.fade_in_async(1, unity_class.color.black, 'linear')

	-- (여)레이첼 (left, smile, idle) : 역시 여름하면 불꽃놀이지! 속이 뻥 뚫리는 기분이야!
	scene_util.play_normal_speech_action(pirate, self,
			{ dir = 'left', sfx = false },
			nil,
			{ name = 'smile' },
			{ key = 'ss_milkyway_main_s6_1_15', skip = true })

	-- (여)레나(right, smile, idle) : 밤 하늘에는 별보다 이쁜 게 없을 줄 알았는데…
	scene_util.play_normal_speech_action(star_girl, self,
			{ dir = 'right', sfx = false },
			nil,
			{ name = 'smile', keep = true },
			{ key = 'ss_milkyway_main_s6_1_16', skip = true })

	-- (여)레나 (right, greed, sing) : 별만큼이나 아름답잖아?!
	music_player_util.play_sfx_one_shot('01_gatcha_point_01')
	scene_util.play_normal_speech_action(star_girl, self,
			{ dir = 'right', sfx = false },
			{ name = 'sing', keep = true },
			{ name = 'greed', keep = true },
