function local_class:shot_firecracker_event()
	self.fireworks_loop = true

	local info_list = self.fireworks_info[self.current_fireworks_round]

	for i = 1, #info_list do
		start_coroutine(self.play_firecracker_in_track, self, i)
	end

	while self.fireworks_loop do
		if #info_list <= self.fireworks_info.track_clear_count then
			self.fireworks_info.track_clear_count = 0

			if self.current_fireworks_round < self.fireworks_round.round_3 then
				self.current_fireworks_round = self.current_fireworks_round + 1
			elseif self.current_fireworks_round >= self.fireworks_round.round_3 then
				self.current_fireworks_round = self.fireworks_round.round_1

				self.fireworks_event_paused = false
			end

			info_list = self.fireworks_info[self.current_fireworks_round]

			for i = 1, #info_list do
				start_coroutine(self.play_firecracker_in_track, self, i)
			end
		end

		coroutine.yield(nil)
	end
end

function local_class:play_firecracker_in_track(track)
	local current_round_info = self.fireworks_info[self.current_fireworks_round]
	local track_info = current_round_info[track]

	for i = 1, #track_info do
		local firecracker_info = track_info[i]
		local fx_color = firecracker_info.color

		if not self.fireworks_info.first_shot then
			if not self:wait_for_sec_to_stop(firecracker_info.wait_time) then
				return
			end
		else
			self.fireworks_info.first_shot = false
		end

		local fireworks_pos = self.markers.fireworks_fx_pos(self.current_fireworks_round, track, i)

		local fx
		if fx_color == self.fireworks_color.blue then
			fx = self.fx:firework_blue():Instantiate(fireworks_pos)
		elseif fx_color == self.fireworks_color.red then
			fx = self.fx:firework_red():Instantiate(fireworks_pos)
		elseif fx_color == self.fireworks_color.green then
			fx = self.fx:firework_green():Instantiate(fireworks_pos)
		elseif fx_color == self.fireworks_color.yellow then
			fx = self.fx:firework_yellow():Instantiate(fireworks_pos)
		elseif fx_color == self.fireworks_color.orange then
			fx = self.fx:firework_orange():Instantiate(fireworks_pos)
		elseif fx_color == self.fireworks_color.mw_blue then
			fx = self.fx:firework_mw_blue():Instantiate(fireworks_pos)
		elseif fx_color == self.fireworks_color.mw_green then
			fx = self.fx:firework_mw_green():Instantiate(fireworks_pos)
		elseif fx_color == self.fireworks_color.purple then
			fx = self.fx:firework_purple():Instantiate(fireworks_pos)
		end

		if fx ~= nil and firecracker_info.scale ~= nil then
			fx.transform.localScale = firecracker_info.scale
		end
	end

	self.fireworks_info.track_clear_count = self.fireworks_info.track_clear_count + 1
end

function local_class:wait_for_sec_to_stop(sec, escape_callback)
	local time_passed = 0
	while time_passed < sec do
		time_passed = time_passed + unity_class.time.deltaTime

		-- 모든 시간 기다리지 않고 탈출
		if self.controller.stage_ended then
			return false
		end

		if self.loop_escape then
			self.loop_escape = false

			return false
		end

		if self.qte_activity_info.current_state == self.qte_activity_state.ending or
				self.qte_activity_info.current_state == self.qte_activity_state.fail then
			return false
		end

		coroutine.yield(nil)
	end

	-- 기다림 완료
	return true
end

