function local_class:concert_hall_before_event()
	local group = self.controller.event_controller:get_group('s6_concert_area')

	local loop_talker = {
		self.pooled_characters(group, 'audience_1'),
		self.pooled_characters(group, 'audience_4'),
		self.pooled_characters(group, 'audience_9'),
		self.pooled_characters(group, 'audience_7'),
	}

	wait_for_sec(0.1)

	self.concert_before_event_loop = true

	while self.concert_before_event_loop do
		-- 꼬마남1 (right, tired, idle): 언제 시작하는 거야?
		self.concert_before_event_talker = loop_talker[1]
		speech_bubble_util.show_speech_bubble_async(loop_talker[1], { key = 'ss_milkyway_main_s6_2_before_1', skip = false })

		-- 3초 뒤
		if not self:wait_for_sec_to_stop(3) then
			self.concert_before_event_talker = nil

			return
		end

		-- 꼬마남3 (left, tired, idle): 조금 춥네…
		self.concert_before_event_talker = loop_talker[2]
		speech_bubble_util.show_speech_bubble_async(loop_talker[2], { key = 'ss_milkyway_main_s6_2_before_2', skip = false })

		-- 3초 뒤
		if not self:wait_for_sec_to_stop(3) then
			self.concert_before_event_talker = nil

			return
		end

		-- 꼬마남5 (right, smile, idle): 너무 기대된다.
		self.concert_before_event_talker = loop_talker[3]
		speech_bubble_util.show_speech_bubble_async(loop_talker[3], { key = 'ss_milkyway_main_s6_2_before_3', skip = false })

		-- 블루 대화 출력 끝나고 1초 뒤
		if not self:wait_for_sec_to_stop(1) then
			self.concert_before_event_talker = nil

			return
		end

		-- 꼬마여3 (left, idle, idle): 곧 시작할 텐데…
		self.concert_before_event_talker = loop_talker[4]
		speech_bubble_util.show_speech_bubble_async(loop_talker[4], { key = 'ss_milkyway_main_s6_2_before_4', skip = false })

		-- 꼬마여3 대사 출력 이후 3초 대기 후 다시 꼬마남 1 대사 출력
		if not self:wait_for_sec_to_stop(3) then
			self.concert_before_event_talker = nil

			return
		end

		coroutine.yield()
	end

	self.concert_before_event_talker = nil
end

function local_class:concert_hall_after_event(rangers)
	-- 컨트롤 풀리면 1초 뒤 비강제 원라인 대사 출력
	wait_for_sec(1)

	-- 레드 (down, idle, idle): 여러분이 위험에 빠지면 오늘 처럼 우리가 날아올 거야!
	speech_bubble_util.show_speech_bubble_async(rangers[3], { key = 'ss_milkyway_main_s6_2_after_1', skip = false })

	-- 3초 뒤
	if not self:wait_for_sec_to_stop(3) then
		return
	end

	-- 핑크 (down, idle, idle): 하지만 나쁜 친구들은 우리가 도와줄 수 없어!
	speech_bubble_util.show_speech_bubble_async(rangers[5], { key = 'ss_milkyway_main_s6_2_after_2', skip = false })

	-- 2초 뒤
	if not self:wait_for_sec_to_stop(2) then
		return
	end

	-- 그린 (down, idle, idle): 맞아! 모두들 우리가 했던 약속 지켜줄거지?!
	speech_bubble_util.show_speech_bubble_async(rangers[1], { key = 'ss_milkyway_main_s6_2_after_3', skip = false })

	-- 블루 대화 출력 끝나고 1초 뒤
	if not self:wait_for_sec_to_stop(1) then
		return
	end

	-- 아래 위치에 shout 말풍선 출력
	speech_bubble_util.show_speech_bubble_async(rangers[4], { key = 'ss_milkyway_main_s6_2_after_4', bubble_type = 'shout',
															  world_pos = self.markers.pirate_kid(2, 1, 1) + vector(-1, 0, 1), skip = false })

	-- shout 말풍선 끝나고 5초 뒤 다시 대화 진행
	if not self:wait_for_sec_to_stop(5) then
		return
	end
end

