function local_class:pub_activity_loop()
	self.qte_activity_info.current_state = self.qte_activity_state.play

	start_coroutine(self.pub_activity_play_trio_man_act, self)
	start_coroutine(self.pub_activity_play_pirate_qte_act, self)

	self.qte_activity_info.cur_time = 0
	while self.qte_activity_info.current_state == self.qte_activity_state.play do

		self.qte_activity_info.cur_time = self.qte_activity_info.cur_time + unity_class.time.deltaTime

		for i = 1, #self.qte_activity_info.speech_event_at_time do
			local event = self.qte_activity_info.speech_event_at_time[i]

			if not event.passed_event then
				if event.event_time < self.qte_activity_info.cur_time then
					event.passed_event = true

					start_coroutine(event.event_func, self)
				end
			end
		end

		if self.qte_activity_info.cur_time >= self.qte_activity_info.play_time then
			self.qte_activity_info.current_state = self.qte_activity_state.fail
		end

		coroutine.yield()
	end

	if self.qte_activity_info.current_state == self.qte_activity_state.ending then
		self:activity_success_event()
	elseif self.qte_activity_info.current_state == self.qte_activity_state.fail then
		self:activity_fail_event()
	end
end

