		item_unique_id = self.qte_activity_info.pirate_beer_item_unique_id .. self.qte_activity_info.pirate_beer_count
	else
		-- 위와 동시에 대니 앞에 있는 탄산 보리차 중 맨 아래에 위치한 탄산 보리차 fx_dead 출력과 함께 사라짐
		self.qte_activity_info.trio_man_beer_count = self.qte_activity_info.trio_man_beer_count + 1

		item_unique_id = self.qte_activity_info.trio_man_beer_item_unique_id .. self.qte_activity_info.trio_man_beer_count
	end

	local beer = self.items:pop_item(item_unique_id)

	-- fx_dead(0.3크기로) 출력
	local vanishing_fx = self.fx:vanishing():Instantiate(beer.Position)

	music_player_util.play_sfx_one_shot('02_explosion_ball_01')

	if vanishing_fx ~= nil then
		vanishing_fx.transform.localScale = unity_class.vector3.one * 0.3
	end

	quest_drop_item_util.dispose_item(beer)
end

function local_class:twist_stumble(fo)
	local dummy = self.characters.princess()

	character_util.remove_anim_and_emotion(dummy)
	character_util.set_position(dummy, fo.Position)
	dummy.SpineController.SpineContainerTransform.gameObject:SetActive(false)

	character_util.set_active_shadow(fo, false)

	local end_process = function()
		character_util.set_position(dummy, vector(999, 0, 999))
		dummy.SpineController.SpineContainerTransform.gameObject:SetActive(true)

		character_util.set_active_shadow(fo, true)
	end

	character_util.spine_set_attachment(fo, '[base]weapon1', 'empty')
	character_util.spine_set_attachment(fo, '[base]weapon2', 'empty')

	music_player_util.play_sfx_one_shot('03_dialogue_tipsy_01')

	-- (right, confused, walk) 자세 전환.
	scene_util.set_emotion(fo, self, 'confused')
	character_util.remove_anim(fo)

	-- 캐릭터 1.2초에 걸쳐 왼쪽으로 15도 회전.
	start_coroutine(self.rotate_by_pivot_offset, self, fo, 15, 1.2)

	-- 위와 동시에 왼쪽으로 1타일 간격으로 1.2초에 걸쳐 이동
	wp_util.move(fo, fo.Position + vector(-0.5, 0, 0), nil, 1.2, { locked_dir = 'right' })
	wp_util.move(dummy, dummy.Position + vector(-0.5, 0, 0), nil, 1.2)

	if not self:wait_for_sec_to_stop(1.3) then
		end_process()

		return false
	end

	-- 캐릭터 0.3초에 걸쳐 다시 오른쪽으로 20도 회전하며 원래 각도로 돌아옴.
	start_coroutine(self.rotate_by_pivot_offset, self, fo, 0, 0.3)

	if not self:wait_for_sec_to_stop(0.3) then
		end_process()

		return false
	end

	-- 캐릭터 1.2초에 걸쳐 오른쪽으로 20도 회전.
	start_coroutine(self.rotate_by_pivot_offset, self, fo, -15, 1.2)

	-- 위와 동시에 오른쪽으로 1타일 간격으로 1.2초에 걸쳐 이동
	wp_util.move(fo, fo.Position + vector(0.5, 0, 0), nil, 1.2, { locked_dir = 'right' })
	wp_util.move(dummy, dummy.Position + vector(0.5, 0, 0), nil, 1.2)

	if not self:wait_for_sec_to_stop(1.3) then
		end_process()

		return false
	end

	-- 캐릭터 0.3초에 걸쳐 다시 왼쪽으로 15도 회전하며 원래 각도로 돌아옴.
	start_coroutine(self.rotate_by_pivot_offset, self, fo, 0, 0.3)

	if not self:wait_for_sec_to_stop(0.3) then
		end_process()

		return false
	end

	-- 돌아옴과 동시에 (right, blush, seat) 동작 출력
	music_player_util.play_sfx_one_shot('01_rustle_01')
	scene_util.set_emotion(fo, self, 'blush')
	scene_util.set_anim(fo, self, { name = 'seat' })

	--대니 (right, blush, seat) 상태에서 shake 0.03세기로 1초간 출력
	character_util.shake(fo, 0.03, 1)

	if not self:wait_for_sec_to_stop(1) then
		end_process()

		return
	end

	end_process()

	return true
end

