	-- QTE 도중 암전 되지 않음.
	self:qte_tap_drink_act(pirate)

	-- [만약 플레이어가 제한시간(36초)가 다 되기전에 모든 QTE를 완료할 경우, 하단의 클리어 연출 자동 진행.
	if self.qte_activity_info.cur_time <= self.qte_activity_info.trio_man_act_end_time.drink_5 then
		self.qte_activity_info.current_state = self.qte_activity_state.ending
	end
end

function local_class:qte_tap_drink_act(fo, blush_emotion, first_qte)
	blush_emotion = lua_helper.get_or_default(blush_emotion, true)
	first_qte = lua_helper.get_or_default(first_qte, false)

	character_util.spine_set_attachment(fo, '[base]weapon1', self.item_sprite.beer_1)
	character_util.spine_set_attachment(fo, '[base]weapon2', 'empty')

	scene_util.set_anim(fo, self, 'dualgun_idle')
	if blush_emotion then
		scene_util.set_emotion(fo, self, 'blush')
	end

	local start_drink = false

	if not first_qte then
		-- 위와 동시에 대니 앞에 있는 탄산 보리차 중 맨 아래에 위치한 탄산 보리차 fx_dead 출력과 함께 사라짐
		self:pick_up_beer(true)
	end

	local drink_anim_duration = spine_util.get_animation_duration(fo, 'dualgun_attack_right')
	local drink_anim_play_time = 0
	local playing_drink_anim = false

	self.qte_activity_info.tap_count_callback = function()
		local speech_event_info = self.qte_activity_info.speech_event_in_qte[self.qte_activity_info.cur_qte_step]
		if speech_event_info ~= nil then
			if speech_event_info.tap_count == self.qte_activity_info.tap_count then
				start_coroutine(speech_event_info.spectator_event_func, self)
			end
		end

		if not playing_drink_anim then
			start_coroutine(function()
				playing_drink_anim = true

				character_util.spine_set_attachment(fo, '[base]weapon2', self.item_sprite.beer_2)
				character_util.spine_set_attachment(fo, '[base]weapon1', 'empty')

				music_player_util.play_sfx_one_shot('01_drinking_01')

				character_util.set_animation_n_times(fo, { name = 'dualgun_attack_right', count = 1, keep_anim = false })

				wait_for_sec(drink_anim_duration + 0.1)

				character_util.spine_set_attachment(fo, '[base]weapon1', self.item_sprite.beer_1)
				character_util.spine_set_attachment(fo, '[base]weapon2', 'empty')

				scene_util.set_anim(fo, self, 'dualgun_idle')

				playing_drink_anim = false
			end)
		end
	end

	message_system:Subscribe(self, typeof(CS.Oak.TouchEvent), 'on_touch_event')
	self.qte_activity_info.cur_qte_type = self.qte_type.tap

	if self.qte_activity_info.tap_count == 1 then
		qte_play_util.show_tap(false)
	else
		qte_play_util.show_turbo_tap(false)
	end

	while self.qte_activity_info.tap_count < self.qte_activity_info.target_tap_count do
		if self.qte_activity_info.current_state == self.qte_activity_state.fail then
			break
		end

		coroutine.yield(nil)
	end

	message_system:Unsubscribe(self, typeof(CS.Oak.TouchEvent))
	self.qte_activity_info.cur_qte_type = self.qte_type.none

	screen_util.close_tutorial_spine()

	self.qte_activity_info.tap_count = 0

	if self.qte_activity_info.current_state == self.qte_activity_state.fail then
		return
	end

	while playing_drink_anim do
		coroutine.yield(nil)
	end

	local speech_event_info = self.qte_activity_info.speech_event_in_qte[self.qte_activity_info.cur_qte_step]
	if speech_event_info ~= nil then
		if speech_event_info.qte_end then
			start_coroutine(speech_event_info.spectator_event_func, self)
		end
	end

	self.qte_activity_info.cur_beer_count = self.qte_activity_info.cur_beer_count + 1

	self.qte_activity_info.cur_qte_step = self.qte_activity_info.cur_qte_step + 1

	wait_for_sec(0.05)
end

function local_class:qte_swipe_twist_stumble_act(fo, talk_after_right_swipe)
	local dummy = self.characters.knight()

	character_util.remove_anim_and_emotion(dummy)
	character_util.set_position(dummy, fo.Position)
	dummy.SpineController.SpineContainerTransform.gameObject:SetActive(false)

	character_util.set_active_shadow(fo, false)

	local end_process = function()
		character_util.set_position(dummy, vector(999, 0, 999))
		dummy.SpineController.SpineContainerTransform.gameObject:SetActive(true)

		character_util.set_active_shadow(fo, true)
	end

	character_util.spine_set_attachment(fo, '[base]weapon1', 'empty')
	character_util.spine_set_attachment(fo, '[base]weapon2', 'empty')

	music_player_util.play_sfx_one_shot('03_dialogue_tipsy_01')

	-- (여)레이첼 (left, confused, dualgun_reload) 로 전환.
	scene_util.set_emotion(fo, self, 'confused')
	character_util.remove_anim(fo)

	-- 레이첼 캐릭터 1.2초에 걸쳐 오른쪽으로 15도 회전.
	start_coroutine(self.rotate_by_pivot_offset, self, fo, -15, 1.2)

	-- 위와 동시에 오른쪽으로 1타일 간격으로 1.2초에 걸쳐 이동
	wp_util.move(fo, fo.Position + vector(0.5, 0, 0), nil, 1.2, { locked_dir = 'left' })
	wp_util.move(dummy, dummy.Position + vector(0.5, 0, 0), nil, 1.2)

	local speech_event_info = self.qte_activity_info.speech_event_in_qte[self.qte_activity_info.cur_qte_step]
	if speech_event_info ~= nil then
		if speech_event_info.enable_event then
			speech_event_info.enable_event = false

			start_coroutine(speech_event_info.spectator_event_func, self)
		end
	end

	if not self:wait_for_sec_to_stop(1.2) then
		end_process()

		return
	end

	message_system:Subscribe(self, typeof(CS.Oak.TouchEvent), 'on_touch_event')
	self.qte_activity_info.cur_qte_type = self.qte_type.swipe

	-- QTE 종류 : 스와이프
	-- 방향 : ←
	-- 제한 시간 : 1초
	-- 횟수 : 1번
	qte_play_util.show_swipe('left', false)

	local time_passed = 0
	local duration = 1
	while time_passed < duration do
		if self.qte_activity_info.swipe_type ~= nil and
				self.qte_activity_info.swipe_type == direction_constants.left then
			break
		elseif self.qte_activity_info.swipe_type == nil then
			if self.qte_activity_info.current_state == self.qte_activity_state.fail then
				break
			end
		end

		time_passed = time_passed + unity_class.time.deltaTime

		coroutine.yield(nil)
	end

	screen_util.close_tutorial_spine()
	self.qte_activity_info.cur_qte_type = self.qte_type.none

	message_system:Unsubscribe(self, typeof(CS.Oak.TouchEvent))

	self.qte_activity_info.swipe_type = nil

	if time_passed >= duration then
		start_coroutine(self.rotate_by_pivot_offset, self, fo, 0, 0.3)

		-- 레이첼 (left, confused, sleep) 1초간 유지
		local anim_duration = spine_util.get_animation_duration(fo, 'sleep')
		scene_util.set_anim(fo, self, { name = 'sleep' })

		start_coroutine(function()
			wait_for_sec(anim_duration * 0.1)

			self.fx:hit():Instantiate(fo.Position + vector(0.25, 0, 0))

			music_player_util.play_sfx_one_shot('01_hit_comic_01')
		end)

		if not self:wait_for_sec_to_stop(1) then
			end_process()

			return
		end

		-- 이후 레이첼 shake 0.03세기로 0.5초 출력
		character_util.shake(fo, 0.03, 0.5)

		-- 이후 (left, confused, seat) 0.7초간 출력
		scene_util.set_anim(fo, self, { name = 'seat' })

		if not self:wait_for_sec_to_stop(0.7) then
			end_process()

			return
		end

		-- 레이첼 (left, confused, idle) 출력
		character_util.remove_anim(fo)

		-- 0.3초 후 QTE 클리어 연출 시작
		if not self:wait_for_sec_to_stop(0.3) then
			end_process()

			return
		end
	else
		-- 성공 시
		-- 레이첼 캐릭터 0.3초에 걸쳐 다시 오른쪽으로 15도 회전하며 원래 각도로 돌아옴.
		start_coroutine(self.rotate_by_pivot_offset, self, fo, 0, 0.3)

		if not self:wait_for_sec_to_stop(0.3) then
			end_process()

			return
		end
	end

	time_passed = 0

	self.qte_activity_info.cur_qte_step = self.qte_activity_info.cur_qte_step + 1

	if self.qte_activity_info.current_state == self.qte_activity_state.fail then
		end_process()

		return
	end

	if talk_after_right_swipe then
		-- (여)레이첼 (right, confused, idle) : 눈이… 핑핑 돈다아…
		speech_bubble_util.show_speech_bubble(fo, { key = 'ss_milkyway_main_s6_activity_pirate_4', type_speed = 0, scale = 0.75, skip = false })
	end

	character_util.remove_anim(fo)

	-- 레이첼 캐릭터 1.2초에 걸쳐 왼쪽으로 15도 회전.
	start_coroutine(self.rotate_by_pivot_offset, self, fo, 15, 1.2)

	-- 위와 동시에 왼쪽으로 1타일 간격으로 1.2초에 걸쳐 이동
	wp_util.move(fo, fo.Position + vector(-0.5, 0, 0), nil, 1.2, { locked_dir = 'left' })
	wp_util.move(dummy, dummy.Position + vector(-0.5, 0, 0), nil, 1.2)

	if not self:wait_for_sec_to_stop(1.2) then
		end_process()

		return
	end

	message_system:Subscribe(self, typeof(CS.Oak.TouchEvent), 'on_touch_event')
	self.qte_activity_info.cur_qte_type = self.qte_type.swipe

	-- QTE 종류 : 스와이프
	-- 방향 : →
	-- 제한 시간 : 1초
	-- 횟수 : 1번
	qte_play_util.show_swipe('right', false)

	while time_passed < duration do
		if self.qte_activity_info.swipe_type ~= nil and
				self.qte_activity_info.swipe_type == direction_constants.right then
			break
		elseif self.qte_activity_info.swipe_type == nil then
			if self.qte_activity_info.current_state == self.qte_activity_state.fail then
				break
			end
		end

		time_passed = time_passed + unity_class.time.deltaTime

		coroutine.yield(nil)
	end

	screen_util.close_tutorial_spine()
	self.qte_activity_info.cur_qte_type = self.qte_type.none

	message_system:Unsubscribe(self, typeof(CS.Oak.TouchEvent))

	self.qte_activity_info.swipe_type = nil

	if time_passed >= duration then
		start_coroutine(self.rotate_by_pivot_offset, self, fo, 0, 0.3)

		-- 레이첼 (left, confused, sleep) 1초간 유지
		local anim_duration = spine_util.get_animation_duration(fo, 'prostrate')
		local clear_anim_duration = false

		scene_util.set_anim(fo, self, { name = 'prostrate' })

		start_coroutine(function()
			wait_for_sec(anim_duration * 0.1)

			self.fx:hit():Instantiate(fo.Position + vector(-0.25, 0, 0))

			music_player_util.play_sfx_one_shot('01_hit_comic_01')

			wait_for_sec(anim_duration * 0.9)

			clear_anim_duration = true
		end)

		if not self:wait_for_sec_to_stop(1) then
			end_process()

			return
		end

		while not clear_anim_duration do
			coroutine.yield(nil)
		end

		-- 이후 레이첼 shake 0.03세기로 0.5초 출력
		character_util.shake(fo, 0.03, 0.5)

		-- 이후 (left, confused, walk4leg에서 정지 상태로 1초)
		scene_util.set_anim(fo, self, { name = 'walk4legs', loop = false })

		if not self:wait_for_sec_to_stop(1) then
			end_process()

			return
		end

		-- 0.3초 후 QTE 클리어 연출 시작
		if not self:wait_for_sec_to_stop(0.3) then
			end_process()

			return
		end
	else
		-- 레이첼 캐릭터 0.3초에 걸쳐 다시 오른쪽으로 15도 회전하며 원래 각도로 돌아옴.
		start_coroutine(self.rotate_by_pivot_offset, self, fo, 0, 0.3)

		if not self:wait_for_sec_to_stop(0.3) then
			end_process()

			return
		end

		-- 돌아옴과 동시에 (left, blush, idle) 상태로 0.3초 출력 뒤 (left, blush, walk4leg 정지 상태) 동작 0.7초간 출력
		scene_util.set_emotion(fo, self, 'blush')
		character_util.remove_anim(fo)
		-- 위 동작 출력과 동시에 shake 0.03세기로 1초간 출력
		character_util.shake(fo, 0.03, 1)

		if not self:wait_for_sec_to_stop(0.3) then
			end_process()

			return
		end

		music_player_util.play_sfx_one_shot('01_dash_04')

		scene_util.set_anim(fo, self, { name = 'walk4legs', scale = 999, loop = false })

		if not self:wait_for_sec_to_stop(0.7) then
			end_process()

			return
		end
	end

	self.qte_activity_info.cur_qte_step = self.qte_activity_info.cur_qte_step + 1

	if self.qte_activity_info.current_state == self.qte_activity_state.fail then
		end_process()

		return
	end

	end_process()
end

function local_class:hero_landing(fo, anim_args, start_pos, dir, end_pos_y, play_end_sfx)
	character_util.set_active_state(fo, 'enabled')
	character_util.set_position(fo, start_pos)
	scene_util.set_direction(fo, dir, false)

	if anim_args ~= nil then
		character_util.remove_anim_and_emotion(fo)
		scene_util.set_anim(fo, self, anim_args)
	end

	local cur_time = unity_class.time.time
	local fall_duration = 0.4
	local free_fall = CS.CalculatorFreeFall(fall_duration, fo.Position.y, end_pos_y)
	while unity_class.time.time - cur_time < fall_duration do
		free_fall:Proceed(unity_class.time.deltaTime)
		local dist_y = free_fall:GetDistance()

		if start_pos.y + dist_y > 0 then
			character_util.set_position(fo, start_pos + vector(0, dist_y, 0), true)
		else
			character_util.set_position(fo, vector(start_pos.x, end_pos_y, start_pos.z))
		end
		coroutine.yield(nil)
	end

	character_util.set_position(fo, vector(start_pos.x, end_pos_y, start_pos.z), false)
	fo.SpineController.ShadowTransform.localPosition = unity_class.vector3.up * 0.03
	self.fx:last_hit():Instantiate(vector(start_pos.x, 1.1, start_pos.z))
	self.fx:hit():Instantiate(vector(start_pos.x, 1.1, start_pos.z))

	if play_end_sfx then
		music_player_util.play_sfx_one_shot('03_mech_stomp_01')

		if lua_helper.reference_equals(fo, self.characters.teatan_ranger_red()) then
			music_player_util.play_stage_music({ name = 'bgm_iron_teatan', state = 'event', mix = 4})
		end
	end
end

function local_class:rotate_by_pivot_offset(fo, degree, duration)
	local start_rotation = fo.transform.localRotation
	local target_rotation = unity_class.quaternion.Euler(0, 0, degree)

	local backup_pos = fo.Position

	local time_passed = 0
	while time_passed < duration do
		time_passed = time_passed + unity_class.time.deltaTime

		local progress = time_passed / duration
		local cur_rotation = unity_class.quaternion.Lerp(start_rotation, target_rotation, progress)

		fo.transform.localRotation = cur_rotation

		if self.qte_activity_info.current_state == self.qte_activity_state.ending or
				self.qte_activity_info.current_state == self.qte_activity_state.fail then

			return
		end

		coroutine.yield(nil)
	end

	fo.transform.localRotation = target_rotation
end

return local_class
